<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Shoe Comparison Layout</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            background: linear-gradient(to right, #ffffff 50%, #000000 50%);
            font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
            display: flex;
            justify-content: center;
            min-height: 100vh;
        }
        .container {
            width: 100%;
            max-width: 900px;
            position: relative;
            padding-top: 30px;
            display: flex;
            flex-direction: column;
            align-items: center;
        }
        .header {
            width: 100%;
            height: 160px;
            position: relative;
            margin-bottom: 20px;
        }
        .logo-adidas {
            position: absolute;
            top: 0;
            left: 10%;
            width: 150px;
            height: 90px;
            display: flex;
            align-items: center;
            justify-content: center;
            border: 1px dashed #ccc;
            color: black;
            font-size: 14px;
            text-align: center;
        }
        .logo-nike {
            position: absolute;
            top: 0;
            right: 10%;
            width: 150px;
            height: 90px;
            display: flex;
            align-items: center;
            justify-content: center;
            border: 1px dashed #555;
            color: white;
            font-size: 14px;
            text-align: center;
        }
        .author-text {
            position: absolute;
            top: 15px;
            right: 50%;
            padding-right: 20px;
            text-align: center;
            color: black;
            font-weight: 900;
        }
        .author-name {
            font-size: 22px;
            letter-spacing: 2px;
        }
        .author-sub {
            font-size: 11px;
            letter-spacing: 1px;
            margin-top: 4px;
        }
        .vs-graphic {
            position: absolute;
            top: 90px;
            left: 50%;
            transform: translateX(-50%);
            width: 120px;
            height: 80px;
            display: flex;
            align-items: center;
            justify-content: center;
            border: 1px dashed #888;
            color: gray;
            font-size: 14px;
            font-weight: bold;
            z-index: 10;
        }
        .shoes-section {
            width: 100%;
            display: flex;
            justify-content: space-between;
            margin-top: 40px;
            margin-bottom: 60px;
            padding: 0 5%;
            box-sizing: border-box;
        }
        .shoe-placeholder {
            width: 42%;
            height: 180px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            text-align: center;
            border: 1px dashed #777;
        }
        .shoe-left {
            color: black;
        }
        .shoe-right {
            color: white;
        }
        .data-table {
            width: 100%;
            display: flex;
            flex-direction: column;
            font-weight: 900;
            padding-bottom: 60px;
        }
        .row {
            display: flex;
            width: 100%;
            margin-bottom: 35px;
            font-size: 26px;
            letter-spacing: 1px;
        }
        .col-left {
            flex: 1;
            text-align: right;
            padding-right: 25px;
            color: black;
        }
        .col-right {
            flex: 1;
            text-align: left;
            padding-left: 25px;
            color: white;
        }
        .row-top {
            font-size: 28px;
            margin-bottom: 45px;
        }
        .row-top .col-left {
            padding-right: 0;
        }
        .row-top .col-right {
            padding-left: 0;
        }
        .row-title {
            font-size: 30px;
            margin-bottom: 40px;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <div class="logo-adidas placeholder">[Adidas Logo: top-left]</div>

            <div class="author-text">
                <div class="author-name">奔跑的小小宇</div>
                <div class="author-sub">RUNNING XIAOYU</div>
            </div>

            <div class="logo-nike placeholder">[Nike Logo: top-right]</div>

            <div class="vs-graphic placeholder">[VS Graphic: centered]</div>
        </div>

        <div class="shoes-section">
            <div class="shoe-placeholder shoe-left placeholder">[Adidas Shoe Image: facing right]</div>
            <div class="shoe-placeholder shoe-right placeholder">[Nike Shoe Image: facing left]</div>
        </div>

        <div class="data-table">
            <div class="row row-top">
                <div class="col-left">5-</div>
                <div class="col-right">10KM</div>
            </div>

            <div class="row row-title">
                <div class="col-left">Takumi Sen9</div>
                <div class="col-right">Streakfly</div>
            </div>

            <div class="row">
                <div class="col-left">181g</div>
                <div class="col-right">165g</div>
            </div>

            <div class="row">
                <div class="col-left">(27/33) 6mm</div>
                <div class="col-right">8mm (26/32)</div>
            </div>

            <div class="row">
                <div class="col-left">LIGHTWEIGHT MESH</div>
                <div class="col-right">织物鞋面</div>
            </div>

            <div class="row">
                <div class="col-left">Lightstrike Pro</div>
                <div class="col-right">ZoomX</div>
            </div>

            <div class="row">
                <div class="col-left">ENERGYROD玻纤柱</div>
                <div class="col-right">半掌碳板</div>
            </div>

            <div class="row">
                <div class="col-left">Continental™</div>
                <div class="col-right">贴片橡胶</div>
            </div>

            <div class="row">
                <div class="col-left">1499</div>
                <div class="col-right">999</div>
            </div>
        </div>
    </div>
</body>
</html>```
